import re
from datetime import datetime, timezone

with open('/app/logs/auditd.log') as f:
    text = f.read()

events = {}
for line in text.strip().split('\n'):
    m = re.search(r'msg=audit\((\d+\.\d+):(\d+)\)', line)
    if m:
        ts, seq = float(m.group(1)), m.group(2)
        events.setdefault((ts, seq), []).append(line)

for (ts, seq), lines in sorted(events.items()):
    dt = datetime.fromtimestamp(ts, tz=timezone.utc).strftime('%Y-%m-%d %H:%M:%S')
    print(f'=== {dt} (ts={ts}, seq={seq}) ===')
    for l in lines:
        print('  ', l)
""}

