import json, csv, re
from datetime import datetime, timezone

def audit_ts_to_str(ts):
    return datetime.fromtimestamp(ts, tz=timezone.utc).strftime('%Y-%m-%d %H:%M:%S')

# Collect events
all_events = []

# 1. dpkg
with open('/app/logs/dpkg.log') as f:
    for line in f:
        line = line.strip()
        if 'status installed' in line or 'install ' in line:
            parts = line.split(' ', 2)
            all_events.append({
                'ts': f'{parts[0]} {parts[1]}',
                'source': 'dpkg',
                'raw': line
            })

# 2. pip
with open('/app/logs/pip_packages.json') as f:
    data = json.load(f)
    for p in data['packages']:
        all_events.append({
            'ts': p['install_time'],
            'source': 'pip',
            'raw': f\"Installed {p['name']} v{p.get('version','')}\"
        })

# 3. dns
with open('/app/logs/dns_queries.log') as f:
    r = csv.DictReader(f)
    for row in r:
        all_events.append({
            'ts': row['timestamp'],
            'source': 'dns',
            'raw': f\"Query {row['query_name']} -> {row['response_ip']}\"
        })

# 4. netflow
with open('/app/logs/netflow.csv') as f:
    r = csv.DictReader(f)
    for row in r:
        all_events.append({
            'ts': row['timestamp'],
            'source': 'netflow',
            'raw': f\"{row['src_ip']}:{row['src_port']} -> {row['dst_ip']}:{row['dst_port']} {row['bytes_sent']}B/{row['bytes_recv']}B {row['flags']} {row['connection_state']}\"
        })

# 5. journal
with open('/app/logs/journal.log') as f:
    for line in f:
        line = line.strip()
        m = re.match(r'^(Mar \d+ \d+:\d+:\d+)\s+(\S+)\s+(.*)$', line)
        if m:
            dt_str = f\"2024-03-15 {m.group(1).split(' ', 1)[1]}\"
            all_events.append({
                'ts': dt_str,
                'source': 'journal',
                'raw': m.group(3)
            })

# 6. auditd
with open('/app/logs/auditd.log') as f:
    text = f.read()

audit_groups = {}
for line in text.strip().split('\n'):
    m = re.search(r'msg=audit\((\d+\.\d+):(\d+)\)', line)
    if m:
        ts_raw = float(m.group(1))
        seq = m.group(2)
        audit_groups.setdefault((ts_raw, seq), []).append(line)

for (ts_raw, seq), lines in sorted(audit_groups.items()):
    ts_str = audit_ts_to_str(ts_raw)
    all_events.append({
        'ts': ts_str,
        'source': 'auditd',
        'raw': ' | '.join([l[:60] for l in lines])
    })

print(f'Total events collected: {len(all_events)}')
""}

